import { describe, expect, it } from 'vitest';
import {
  PLAYER_CHOICES,
  buildLinuxInstallerSh,
  buildLinuxUninstallerSh,
  buildOpenerCmd,
  buildUninstallerCmd,
  orderedPlayerIds,
  osFromUa,
  playerChoicesFor,
  readPlayerPreference,
  savePlayerPreference,
  PLAYER_PREF_KEY,
} from './openerInstaller';

